+    expect(CLIENT_APPS['1fec8e78-bce4-4aaf-ab1b-5451cc387264']?.foci).toBe(true);
+    expect(CLIENT_APPS['9ba1a5c7-f17a-4de9-a1f1-6178c8d51223']?.note).toContain('条件访问');
