+    expect(clientApp('1fec8e78-bce4-4aaf-ab1b-5451cc387264')?.critical).toBe(true);
+    expect(clientApp('c44b4083-3bb0-49c1-b47d-974e53cbdf3c')?.critical).toBe(true);
